  bool need_sanitize = false;
  auto s = query.target_.validate(field_schema, &need_sanitize);
  CHECK_RETURN_STATUS_EXPECTED(s);

  if (!need_sanitize) {
    return sql_engine_->execute_group_by(schema_, query, segments);
  }

